import csv, statistics, math
from datetime import date
rows=list(csv.DictReader(open('data.csv')))
bands=['VH','VV','VV-VH']
periods=sorted(set(r['period_id'] for r in rows))
pdate={r['period_id']:r['date'] for r in rows}
def pd(s):
    y,m,d=map(int,s.split('-')); return date(y,m,d)
t0=pd(pdate[periods[0]])
t=[(pd(pdate[p])-t0).days for p in periods]
S={b:[] for b in bands}
for p in periods:
    for r in rows:
        if r['period_id']==p: S[r['band']].append(float(r['y']))

def ols(X,y):
    n=len(X[0])
    XtX=[[sum(X[k][i]*X[k][j] for k in range(len(X))) for j in range(n)] for i in range(n)]
    Xty=[sum(X[k][i]*y[k] for k in range(len(X))) for i in range(n)]
    A=[XtX[i][:]+[Xty[i]] for i in range(n)]
    for i in range(n):
        p=max(range(i,n),key=lambda r:abs(A[r][i])); A[i],A[p]=A[p],A[i]
        if abs(A[i][i])<1e-12: continue
        for r in range(n):
            if r!=i:
                f=A[r][i]/A[i][i]
                for c in range(i,n+1): A[r][c]-=f*A[i][c]
    return [A[i][n]/A[i][i] if abs(A[i][i])>1e-12 else 0.0 for i in range(n)]

def seas_design(ts): return [[1.0,math.sin(2*math.pi*x/365.25),math.cos(2*math.pi*x/365.25)] for x in ts]
def full_design(ts): return [[1.0,math.sin(2*math.pi*x/365.25),math.cos(2*math.pi*x/365.25),float(x)] for x in ts]

def predict(name,ytr,ttr,tte):
    if name=='mean': return [statistics.mean(ytr)]*len(tte)
    if name=='persist': return [ytr[-1]]*len(tte)
    if name=='seas':
        b=ols(seas_design(ttr),ytr); return [sum(b[i]*r[i] for i in range(3)) for r in seas_design(tte)]
    if name=='seas_trend':
        b=ols(full_design(ttr),ytr); return [sum(b[i]*r[i] for i in range(4)) for r in full_design(tte)]
    if name=='seas_trend_damp':
        b=ols(full_design(ttr),ytr); tmax=max(ttr)
        out=[]
        for x in tte:
            xd=x if x<=tmax else tmax+0.3*(x-tmax)
            r=[1.0,math.sin(2*math.pi*xd/365.25),math.cos(2*math.pi*xd/365.25),xd]
            out.append(sum(b[i]*r[i] for i in range(4)))
        return out
    if name=='clim':  # average same day-of-year across years
        out=[]
        for x in tte:
            doy=x%365.25
            cand=[ytr[i] for i in range(len(ttr)) if min(abs(ttr[i]%365.25-doy),365.25-abs(ttr[i]%365.25-doy))<20]
            out.append(statistics.mean(cand) if cand else statistics.mean(ytr))
        return out
    if name=='seas_recent':  # seasonal fit on last 60
        k=min(60,len(ytr)); b=ols(seas_design(ttr[-k:]),ytr[-k:])
        return [sum(b[i]*r[i] for i in range(3)) for r in seas_design(tte)]

names=['mean','persist','seas','seas_trend','seas_trend_damp','clim','seas_recent']
folds=[(60,27),(70,27),(80,27),(90,27)]
agg={n:[] for n in names}
for ntr,nte in folds:
    for b in bands:
        y=S[b]
        for n in names:
            pr=predict(n,y[:ntr],t[:ntr],t[ntr:ntr+nte])
            agg[n].append(statistics.mean(abs(a-c) for a,c in zip(pr,y[ntr:ntr+nte])))
print("AVG MAE across folds & bands:")
for n in names: print("  %-16s %.4f"%(n,statistics.mean(agg[n])))
