import csv, datetime, math
import numpy as np
rows=list(csv.DictReader(open("data.csv")))
pids=[]; d={}
for r in rows:
    if r["period_id"] not in pids: pids.append(r["period_id"])
    d[r["period_id"]]=r["date"]
byband={}
for r in rows: byband.setdefault(r["band"],{})[r["period_id"]]=float(r["y"])
dates=[datetime.date.fromisoformat(d[p]) for p in pids]
t0=dates[0]
t=np.array([(dt-t0).days for dt in dates],float)

def design(t, nharm=3, trend=True):
    cols=[np.ones_like(t)]
    yr=365.25
    for k in range(1,nharm+1):
        cols.append(np.sin(2*np.pi*k*t/yr))
        cols.append(np.cos(2*np.pi*k*t/yr))
    if trend: cols.append(t/yr)
    return np.column_stack(cols)

# CV: train on all but last 27, predict last 27
for nharm in [1,2,3,4]:
  for trend in [True,False]:
    errs=[]
    for b in byband:
        y=np.array([byband[b][p] for p in pids])
        X=design(t,nharm,trend)
        tr=slice(0,len(t)-27); te=slice(len(t)-27,len(t))
        beta,_,_,_=np.linalg.lstsq(X[tr],y[tr],rcond=None)
        pred=X[te]@beta
        errs.append(np.mean(np.abs(pred-y[te])))
    print("nharm",nharm,"trend",trend,"MAE",round(np.mean(errs),4))
PY
