w=2*math.pi/365.25
def design(t,K,trend):
    cols=[np.ones(len(t))]
    if trend: cols.append(t)
    for k in range(1,K+1): cols+=[np.sin(k*w*t),np.cos(k*w*t)]
    return np.column_stack(cols)
# backtest: train on t < cutoff (last 365 days held out)
for b in ['VH','VV','VV-VH']:
    t=np.array([x[0] for x in data[b]],float); y=np.array([x[1] for x in data[b]])
    cutoff=t.max()-365
