    for k in range(1,K+1): cols+=[np.sin(k*w*t),np.cos(k*w*t)]
    return np.column_stack(cols)
cfg={'VH':(3,True),'VV':(4,False),'VV-VH':(5,False)}
# targets
tgt=list(csv.DictReader(open('visits_to_predict.csv')))
