def seasonal_w(train, target_date, window, halflife):
    td=doy(target_date); num=0; den=0
    for d,v in train:
        dd=doy(d); diff=abs(dd-td); diff=min(diff,365-diff)
        if diff<=window:
            age=(target_date-d).days
            w=0.5**(age/halflife)
            num+=w*v; den+=w
    return num/den if den else None

def harmonic(train, target_date, K=2, halflife=None):
    # fit y = a0 + sum ak cos + bk sin on doy, weighted
    X=[];Y=[];W=[]
    for d,v in train:
        t=2*math.pi*doy(d)/365.25
        row=[1.0]
        for k in range(1,K+1):
            row.append(math.cos(k*t)); row.append(math.sin(k*t))
        X.append(row);Y.append(v)
        W.append(1.0 if halflife is None else 0.5**((target_date-d).days/halflife))
    # weighted least squares via normal equations
    n=len(X[0])
    A=[[0.0]*n for _ in range(n)]; b=[0.0]*n
    for row,y,w in zip(X,Y,W):
        for i in range(n):
            b[i]+=w*row[i]*y
            for j in range(n): A[i][j]+=w*row[i]*row[j]
    # gaussian elim
    for i in range(n):
        p=max(range(i,n),key=lambda r:abs(A[r][i])); A[i],A[p]=A[p],A[i]; b[i],b[p]=b[p],b[i]
