    for i in range(n-1,-1,-1):
        s=b[i]-sum(A[i][j]*coef[j] for j in range(i+1,n))
        coef[i]=s/A[i][i]
    t=2*math.pi*doy(target_date)/365.25
    row=[1.0]
    for k in range(1,K+1): row.append(math.cos(k*t)); row.append(math.sin(k*t))
    return sum(c*r for c,r in zip(coef,row))

