import csv, datetime, statistics, math
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
series=defaultdict(dict); dates={}
for r in rows:
    series[r['band']][r['period_id']]=float(r['y']); dates[r['period_id']]=r['date']
pids=sorted(dates, key=lambda p: dates[p])
start=datetime.date.fromisoformat(dates[pids[0]])
def doy(p):
    d=datetime.date.fromisoformat(dates[p]); return (d-start).days

def clim(b,td,train,bw):
    num=den=0.0
    for p in train:
        dd=abs(doy(p)-td); dd=min(dd,365-dd)
        w=math.exp(-0.5*(dd/bw)**2); num+=w*series[b][p]; den+=w
    return num/den if den>0 else statistics.mean(series[b][p] for p in train)

def lastyear(b,td,train):
    # nearest point in train with doy closest to td-365 (or td+365)
    best=None;bd=1e9
    for p in train:
        for off in (-365,0,365):
            dd=abs(doy(p)-(td+off))
            if dd<bd: bd=dd;best=p
    return series[b][best]

train=[p for p in pids if doy(p)<3*365]
test=[p for p in pids if 3*365<=doy(p)<4*365]

for name,fn in [("clim20",lambda b,td:clim(b,td,train,20)),
                ("clim30",lambda b,td:clim(b,td,train,30)),
                ("lastyear",lambda b,td:lastyear(b,td,train))]:
    errs=[abs(fn(b,doy(p))-series[b][p]) for b in series for p in test]
    print(name, round(statistics.mean(errs),4))

# blend clim + lastyear
for a in [0.3,0.5,0.7]:
    errs=[]
    for b in series:
        for p in test:
            td=doy(p)
            pred=a*clim(b,td,train,25)+(1-a)*lastyear(b,td,train)
            errs.append(abs(pred-series[b][p]))
    print("blend a=",a,round(statistics.mean(errs),4))
