def doy(d): return d.timetuple().tm_yday

def seasonal_forecast(hist, target_date, halfwidth=20, sigma=12):
    # hist: list of (date,val) strictly before target
    td=doy(target_date)
    num=0.0; den=0.0
    for d,v in hist:
        dd=abs(doy(d)-td)
        dd=min(dd,365-dd)  # wrap
        if dd<=halfwidth:
            w=math.exp(-0.5*(dd/sigma)**2)
            num+=w*v; den+=w
    return num/den if den>0 else None

# Holdout: predict last 55 obs (2023-09 onward) using earlier data
for b in ["VH","VV","VV-VH"]:
    series=by[b]
    cut=len(series)-55
    hist=series[:cut]
    errs=[]
    for d,v in series[cut:]:
        p=seasonal_forecast(hist,d)
        if p is not None: errs.append(abs(p-v))
    print(b,"holdout MAE",round(statistics.mean(errs),3),"n",len(errs),"std",round(statistics.pstdev([v for _,v in series]),3))
