t={p:pd(dates[p]) for p in pids}
t0=t[pids[0]]
days={p:(t[p]-t0).days for p in pids}
doy={p:t[p].timetuple().tm_yday for p in pids}
cut=date(2023,9,21)
train=[p for p in pids if t[p]<cut]; test=[p for p in pids if t[p]>=cut]

def solve(A,b):
    # normal equations
    n=len(A[0])
    AtA=[[sum(A[k][i]*A[k][j] for k in range(len(A))) for j in range(n)] for i in range(n)]
    Atb=[sum(A[k][i]*b[k] for k in range(len(A))) for i in range(n)]
    # gaussian elim
    M=[AtA[i][:]+[Atb[i]] for i in range(n)]
    for c in range(n):
        piv=max(range(c,n),key=lambda r:abs(M[r][c]))
        M[c],M[piv]=M[piv],M[c]
        if abs(M[c][c])<1e-12: continue
        for r in range(n):
            if r!=c:
                f=M[r][c]/M[c][c]
                for k in range(c,n+1): M[r][k]-=f*M[c][k]
