    t=2*math.pi*doy(date)/365.25
    row=[1.0]
    for k in range(1,K+1): row+=[math.cos(k*t),math.sin(k*t)]
    return sum(c*r for c,r in zip(coef,row))

def backtest_harm(cutoff,K):
    train=[p for p in pids if ds[p]<cutoff]
    test=[p for p in pids if ds[p]>=cutoff and ds[p]<cutoff+datetime.timedelta(days=365)]
    errs=defaultdict(list)
    for b in bands:
        coef=harm_fit(train,b,K)
        for p in test: errs[b].append(abs(harm_pred(coef,ds[p],K)-d[b][p]))
    return {b:round(statistics.mean(e),3) for b,e in errs.items()}

