import csv, datetime, statistics, math
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
ser=defaultdict(list)
for r in rows:
    ser[r["band"]].append((datetime.date.fromisoformat(r["date"]), float(r["y"])))
for b in ser: ser[b].sort()

def fit_predict(train, test_dates, method):
    vals=[v for d,v in train]; dates=[d for d,v in train]
    n=len(vals); mean=statistics.mean(vals)
    if method=="mean":
        return [mean]*len(test_dates)
    if method=="persist":
        return [vals[-1]]*len(test_dates)
    if method=="seasonal":
        mm=defaultdict(list)
        for d,v in train: mm[d.month].append(v)
        gm=mean
        return [statistics.mean(mm[d.month]) if mm[d.month] else gm for d in test_dates]
    if method=="seasonal_trend":
        # linear trend + monthly residual
        xs=list(range(n)); mx=statistics.mean(xs)
        slope=sum((xs[i]-mx)*(vals[i]-mean) for i in range(n))/sum((x-mx)**2 for x in xs)
        intercept=mean-slope*mx
        resid=defaultdict(list)
        for i,(d,v) in enumerate(train):
            resid[d.month].append(v-(intercept+slope*i))
        out=[]
        for j,d in enumerate(test_dates):
            i=n+j
            r=statistics.mean(resid[d.month]) if resid[d.month] else 0
            out.append(intercept+slope*i+r)
        return out
    if method=="seasonal_week":  # use day-of-year binning (half-month)
        pass

# backtest: hold out last 27, train on rest
