import csv, datetime, statistics, math
from collections import defaultdict
rows=list(csv.DictReader(open("data.csv")))
byband=defaultdict(list)
for r in rows:
    byband[r["band"]].append((datetime.date.fromisoformat(r["date"]), float(r["y"])))
for b in byband: byband[b].sort()
def doy(d): return d.timetuple().tm_yday

def fit_harm(hist,K,trend):
    n=len(hist); X=[];Y=[]
    t0=hist[0][0]
    for hd,hv in hist:
        t=2*math.pi*doy(hd)/365.25
        row=[1.0]
        for k in range(1,K+1): row+=[math.cos(k*t),math.sin(k*t)]
        if trend: row.append((hd-t0).days/365.25)
        X.append(row);Y.append(hv)
    p=len(X[0])
    A=[[sum(X[i][a]*X[i][bb] for i in range(n)) for bb in range(p)] for a in range(p)]
    bv=[sum(X[i][a]*Y[i] for i in range(n)) for a in range(p)]
    for i in range(p):
        piv=A[i][i]
        for j in range(i+1,p):
            f=A[j][i]/piv
            for k in range(i,p): A[j][k]-=f*A[i][k]
            bv[j]-=f*bv[i]
    coef=[0]*p
    for i in range(p-1,-1,-1):
        coef[i]=(bv[i]-sum(A[i][j]*coef[j] for j in range(i+1,p)))/A[i][i]
    return coef,t0

def pred_harm(coef,t0,d,K,trend):
    t=2*math.pi*doy(d)/365.25
    row=[1.0]
    for k in range(1,K+1): row+=[math.cos(k*t),math.sin(k*t)]
    if trend: row.append((d-t0).days/365.25)
    return sum(c*r for c,r in zip(coef,row))

all_dates=sorted(set(d for d,_ in byband["VH"]))
cutoffs=[datetime.date(2022,9,28),datetime.date(2023,3,28),datetime.date(2023,9,28),datetime.date(2024,3,28)]

def eval_method(fn):
    tot=[]
    for b in byband:
        for cut in cutoffs:
            hist=[(d,v) for d,v in byband[b] if d<cut]
            if len(hist)<20: continue
            targets=[d for d in all_dates if d>=cut][:27]
            act={d:v for d,v in byband[b]}
            errs=[abs(fn(hist,d)-act[d]) for d in targets if d in act]
            tot+=errs
    return statistics.mean(tot)

for K in [1,2,3,4]:
    for trend in [False,True]:
        def fn(h,d,K=K,trend=trend):
            c,t0=fit_harm(h,K,trend); return pred_harm(c,t0,d,K,trend)
        print(f"K={K} trend={trend} MAE",round(eval_method(fn),3))
