for r in rows:
    data[r["band"]].append((datetime.date.fromisoformat(r["date"]), float(r["y"])))
for b in bands: data[b].sort()

def design(dates, t0, nharm, trend):
    t = np.array([(d-t0).days for d in dates], float)
    doy = np.array([d.timetuple().tm_yday for d in dates], float)
    cols = [np.ones_like(t)]
    if trend: cols.append(t)
    for k in range(1, nharm+1):
        cols.append(np.sin(2*np.pi*k*doy/365.25)); cols.append(np.cos(2*np.pi*k*doy/365.25))
    return np.column_stack(cols)

def fit_pred(train, test, nharm, trend):
    t0 = train[0][0]
    Xtr = design([d for d,_ in train], t0, nharm, trend)
    y = np.array([v for _,v in train])
    c,*_ = np.linalg.lstsq(Xtr, y, rcond=None)
    return design([d for d,_ in test], t0, nharm, trend)@c

for b in bands:
    s = data[b]
    print(f"\n=== {b} ===")
    best=None
    for nh in [2,3,4,5]:
