    series[r["band"]][r["period_id"]]=float(r["y"]); dates[r["period_id"]]=r["date"]
    if r["period_id"] not in order: order.append(r["period_id"])
order=sorted(order)
def pd(s):
    y,m,d=map(int,s.split("-")); return date(y,m,d)
ds=[pd(dates[p]) for p in order]
t=[(d-ds[0]).days for d in ds]

def row(x,K,trend):
    r=[]
    for k in range(1,K+1):
        r.append(math.sin(2*math.pi*k*x/365.25)); r.append(math.cos(2*math.pi*k*x/365.25))
    if trend: r.append(x/365.25)
    r.append(1.0); return r
def lstsq(A,y):
    n=len(A); p=len(A[0])
    AtA=[[sum(A[i][a]*A[i][b] for i in range(n)) for b in range(p)] for a in range(p)]
    Aty=[sum(A[i][a]*y[i] for i in range(n)) for a in range(p)]
    M=[AtA[i][:]+[Aty[i]] for i in range(p)]
    for c in range(p):
        piv=max(range(c,p), key=lambda r: abs(M[r][c])); M[c],M[piv]=M[piv],M[c]
        if abs(M[c][c])<1e-12: continue
        for r in range(p):
            if r!=c:
                f=M[r][c]/M[c][c]
                for k in range(c,p+1): M[r][k]-=f*M[c][k]
    return [M[i][p]/M[i][i] if abs(M[i][i])>1e-12 else 0 for i in range(p)]

# rolling origin: holdout blocks of 27, origins at n-27, n-54, n-81
