import csv, statistics, math, json
from collections import defaultdict
from datetime import date

def load(path="data.csv"):
    rows=list(csv.DictReader(open(path)))
    periods=[]; seen=set()
    for r in rows:
        if r["period_id"] not in seen:
            seen.add(r["period_id"]); periods.append((r["period_id"],r["date"]))
    pidx={p:i for i,(p,d) in enumerate(periods)}
    dates=[date.fromisoformat(d) for p,d in periods]
    bands=sorted(set(r["band"] for r in rows))
    series=defaultdict(lambda:[None]*len(periods))
    for r in rows:
        series[r["band"]][pidx[r["period_id"]]]=float(r["y"])
    return periods, dates, bands, series

def circdist(a,b):
    d=abs(a-b)%365.25
    return min(d,365.25-d)

def predict_doy(dates, vals, target_doy, bw, exclude_year=None, level_adj=None):
    num=0.0; den=0.0
    for d,v in zip(dates,vals):
        if v is None: continue
        if exclude_year is not None and d.year==exclude_year: continue
        doy=d.timetuple().tm_yday
        w=math.exp(-0.5*(circdist(doy,target_doy)/bw)**2)
        if w<1e-6: continue
        vv=v
        if level_adj is not None:
            vv=v-level_adj.get(d.year,0.0)
        num+=w*vv; den+=w
    if den==0: return None
    return num/den

def loyo_cv(dates, vals, bw):
    errs=[]
    years=set(d.year for d in dates)
    for y in years:
        for d,v in zip(dates,vals):
            if d.year!=y or v is None: continue
            p=predict_doy(dates,vals,d.timetuple().tm_yday,bw,exclude_year=y)
            if p is not None: errs.append(abs(p-v))
    return statistics.mean(errs) if errs else float('inf')

if __name__=="__main__":
    periods,dates,bands,series=load()
    for b in bands:
        best=None
        for bw in [5,8,10,12,15,20,25,30,40,50,60]:
            m=loyo_cv(dates,series[b],bw)
            if best is None or m<best[1]: best=(bw,m)
        print(b,"best bw",best[0],"LOYO MAE",round(best[1],3))
