from collections import defaultdict
from datetime import date

def load(path="data.csv"):
    rows=list(csv.DictReader(open(path)))
    periods=[]; seen=set()
    for r in rows:
        if r["period_id"] not in seen:
            seen.add(r["period_id"]); periods.append((r["period_id"],r["date"]))
