    series=defaultdict(lambda:[None]*len(periods))
    for r in rows:
        series[r["band"]][pidx[r["period_id"]]]=float(r["y"])
    return periods, dates, bands, series

def circdist(a,b):
    d=abs(a-b)%365.25
    return min(d,365.25-d)

def kernel_weights(dates, target_doy, bw, exclude_year=None):
    out=[]
    for d in dates:
        if exclude_year is not None and d.year==exclude_year:
            out.append(0.0); continue
        doy=d.timetuple().tm_yday
        w=math.exp(-0.5*(circdist(doy,target_doy)/bw)**2)
        out.append(w if w>1e-6 else 0.0)
    return out

def pred_mean(dates,vals,target_doy,bw,exclude_year=None):
    w=kernel_weights(dates,target_doy,bw,exclude_year)
    num=den=0.0
    for wi,v in zip(w,vals):
        if v is None or wi==0: continue
        num+=wi*v; den+=wi
    return num/den if den>0 else None

def pred_robust(dates,vals,target_doy,bw,exclude_year=None,k=1.5):
    w=kernel_weights(dates,target_doy,bw,exclude_year)
