def design(d, t, K, trend):
    x=[1.0]
    if trend: x.append(t)
    for k in range(1,K+1):
        ang=2*math.pi*k*doy(d)/365.25
        x.append(math.cos(ang)); x.append(math.sin(ang))
    return x
def solve_ls(X,y):
    n=len(X[0]); A=[[0.0]*n for _ in range(n)]; b=[0.0]*n
    for xi,yi in zip(X,y):
        for i in range(n):
            b[i]+=xi[i]*yi
            for j in range(n): A[i][j]+=xi[i]*xi[j]
    for i in range(n):
        p=max(range(i,n),key=lambda r:abs(A[r][i]))
        A[i],A[p]=A[p],A[i]; b[i],b[p]=b[p],b[i]
        if abs(A[i][i])<1e-12: continue
        for r in range(i+1,n):
            f=A[r][i]/A[i][i]
            for c in range(i,n): A[r][c]-=f*A[i][c]
            b[r]-=f*b[i]
    x=[0.0]*n
    for i in range(n-1,-1,-1):
        if abs(A[i][i])<1e-12: x[i]=0; continue
        s=b[i]-sum(A[i][j]*x[j] for j in range(i+1,n)); x[i]=s/A[i][i]
