def predict_kernel(hist, target_doy, bw, exclude_year=None):
    # kernel weighted average over hist points by doy distance
    num=0; den=0
    for (y,dd,v) in hist:
        if exclude_year is not None and y==exclude_year: continue
        w=math.exp(-0.5*(circdist(dd,target_doy)/bw)**2)
        num+=w*v; den+=w
    return num/den if den>0 else None

