import csv, statistics, datetime, collections
rows=list(csv.DictReader(open("data.csv")))
bands=['B11','B12','B2','B3','B4','B8','NDVI','NDWI']
periods=[]; seen=set()
for r in rows:
    if r["period_id"] not in seen:
        seen.add(r["period_id"]); periods.append(r["period_id"])
dates={r["period_id"]:r["date"] for r in rows}
series={b:{} for b in bands}
for r in rows: series[r["band"]][r["period_id"]]=float(r["y"])

def doy(d):
    y,m,dd=map(int,d.split("-"))
    return datetime.date(y,m,dd).timetuple().tm_yday

# mark outliers: cloud contamination -> NDVI<0.1 AND B4 high, or B8>4000
outliers=set()
for p in periods:
    if series['NDVI'][p]<0.1 and series['B4'][p]>3000:
        outliers.add(p)
print("outliers:", sorted(outliers))

# seasonal analog predictor: for target doy, gather historical obs within window, take median
def predict_analog(target_doy, hist_periods, window=20):
    cands=[]
    for p in hist_periods:
        if p in outliers: continue
        d=doy(dates[p])
        diff=abs(d-target_doy); diff=min(diff,365-diff)
        if diff<=window:
            cands.append((diff,p))
    if not cands: return None
    # weight by inverse distance
    out={}
    for b in bands:
        vals=[(1.0/(dd+1), series[b][p]) for dd,p in cands]
        tot=sum(w for w,_ in vals)
        out[b]=sum(w*v for w,v in vals)/tot
    return out

# Backtest: predict last 12 months (2023-10-01 onward) using data before
cut=datetime.date(2023,10,1)
hist=[p for p in periods if datetime.date(*map(int,dates[p].split("-")))<cut]
test=[p for p in periods if datetime.date(*map(int,dates[p].split("-")))>=cut and p not in outliers]
print("hist",len(hist),"test",len(test))
for window in [10,15,20,25,30]:
    errs={b:[] for b in bands}
    for p in test:
        pred=predict_analog(doy(dates[p]),hist,window)
        if pred is None: continue
        for b in bands:
            errs[b].append(abs(pred[b]-series[b][p]))
    mae={b:statistics.mean(errs[b]) for b in bands}
    print(f"window={window}", {b:round(mae[b],3) for b in bands})
