    d=abs(a-b); return min(d,365.25-d)

def clim_pred(b, target_p, train, bw):
    td=doy(dates[target_p])
    num=0;den=0
    for p in train:
        d=circdist(td,doy(dates[p]))
        w=math.exp(-0.5*(d/bw)**2)
        num+=w*series[b][p]; den+=w
    return num/den if den>0 else statistics.mean(series[b][p] for p in train)

