import csv, datetime, math, statistics
rows=list(csv.DictReader(open("data.csv")))
bands=['B11','B12','B2','B3','B4','B8','NDVI','NDWI']
periods=[]; seen={}
for r in rows:
    p=r["period_id"]
    if p not in seen:
        seen[p]={"date":r["date"]}; periods.append(p)
    seen[p][r["band"]]=float(r["y"])
for p in periods:
    d=datetime.date.fromisoformat(seen[p]["date"])
    seen[p]["doy"]=d.timetuple().tm_yday
    seen[p]["year"]=d.year
    seen[p]["t"]=(d-datetime.date(2020,1,1)).days

def doy_dist(a,b):
    d=abs(a-b)%365.25
    return min(d,365.25-d)

def analog_predict(train, test, band, bw, year_decay):
    preds=[]
    for p in test:
        ws=[]; vs=[]
        for q in train:
            dd=doy_dist(seen[p]["doy"],seen[q]["doy"])
            w=math.exp(-0.5*(dd/bw)**2)
            if year_decay>0:
                w*=math.exp(-(seen[p]["year"]-seen[q]["year"])/year_decay)
            ws.append(w); vs.append(seen[q][band])
        s=sum(ws)
        preds.append(sum(w*v for w,v in zip(ws,vs))/s if s>0 else statistics.mean(vs))
    return preds

def fourier_design(doy,K):
    x=[1.0]
    for k in range(1,K+1):
        x.append(math.cos(2*math.pi*k*doy/365.25)); x.append(math.sin(2*math.pi*k*doy/365.25))
    return x
def solve(A,b):
    n=len(A[0])
    AtA=[[sum(A[r][i]*A[r][j] for r in range(len(A))) for j in range(n)] for i in range(n)]
    Atb=[sum(A[r][i]*b[r] for r in range(len(A))) for i in range(n)]
    for i in range(n): AtA[i][i]+=1e-6
    M=[AtA[i][:]+[Atb[i]] for i in range(n)]
    for c in range(n):
        piv=max(range(c,n),key=lambda r:abs(M[r][c])); M[c],M[piv]=M[piv],M[c]
        pv=M[c][c]
        if abs(pv)<1e-12: continue
        for r in range(n):
            if r!=c:
                f=M[r][c]/pv
                for k in range(c,n+1): M[r][k]-=f*M[c][k]
    return [M[i][n]/M[i][i] if abs(M[i][i])>1e-12 else 0 for i in range(n)]
def fourier_predict(train,test,band,K,trend):
    A=[];b=[]
    for p in train:
        x=fourier_design(seen[p]["doy"],K)
        if trend: x=x+[seen[p]["t"]/1000.0]
        A.append(x); b.append(seen[p][band])
    coef=solve(A,b); preds=[]
    for p in test:
        x=fourier_design(seen[p]["doy"],K)
        if trend: x=x+[seen[p]["t"]/1000.0]
        preds.append(sum(c*xx for c,xx in zip(coef,x)))
    return preds

# CV: hold out each year 2022,2023,2024
for band in bands:
    res={}
    for hold in [2022,2023,2024]:
        train=[p for p in periods if seen[p]["year"]!=hold]
        test=[p for p in periods if seen[p]["year"]==hold]
        actual=[seen[p][band] for p in test]
        # analog grid
        for bw in [10,20,30,45,60]:
            for yd in [0,1,2,3]:
                pr=analog_predict(train,test,band,bw,yd)
                mae=statistics.mean(abs(a-b) for a,b in zip(actual,pr))
                res.setdefault(("analog",bw,yd),[]).append(mae)
        for K in [2,3,4]:
            for tr in [False,True]:
                pr=fourier_predict(train,test,band,K,tr)
                mae=statistics.mean(abs(a-b) for a,b in zip(actual,pr))
                res.setdefault(("fourier",K,tr),[]).append(mae)
    best=sorted(res.items(),key=lambda kv:statistics.mean(kv[1]))[:3]
    print(band, [(k,round(statistics.mean(v),3)) for k,v in best])
